import { FLR, getPlayerName, getLang } from './utils.js';
import { safeStorage, safeCrypto } from './safeStorage.js';
import { secureStorage } from './secureStorage.js';


function generateSignature(alt, coins, playTime, lang) {
  const salt = "E7eRn4L_JumP_Pr0t3ct10n";
  let str = alt + "_" + (coins || 0) + "_" + Math.floor(playTime / 1000) + "_" + lang + "_" + salt;
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
      let char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
  }
  return hash.toString(36);
}

export const LootLockerAPI = {
  hasLootLockerConfig: null,
  isDirectMode: false,
  apiKey: import.meta.env.VITE_LOOTLOCKER_API_KEY || '',
  domainKey: import.meta.env.VITE_LOOTLOCKER_DOMAIN_KEY || '',
  leaderboardId: import.meta.env.VITE_LOOTLOCKER_LEADERBOARD_ID || '',
  taLeaderboardId: import.meta.env.VITE_LOOTLOCKER_TA_LEADERBOARD_ID || '',
  coinLeaderboardId: import.meta.env.VITE_LOOTLOCKER_COIN_LEADERBOARD_ID || '',
  playerIdentifier: import.meta.env.DEV ? 'p_86fd8b1a11bda28f' : safeStorage.getItem('LL_PID'),

  sessionToken: null,
  playerId: null,
  version: `v${import.meta.env.VITE_APP_VERSION}`,
  logs: [],

  log: function(msg, type = 'info') {
    const timestamp = new Date().toLocaleTimeString();
    this.logs.push({ timestamp, msg, type });
    if (type === 'error' || type === 'warning') {
      console.warn(`[LootLocker ${type.toUpperCase()}] ${msg}`);
    }
  },


  checkConfig: async function() {
    if (this.hasLootLockerConfig !== null) return this.hasLootLockerConfig;

    this.log('Checking LootLocker configuration...', 'info');

    // 1. Try Express Proxy backend check first
    try {
      this.log('Checking Express Server proxy availability...', 'info');
      let r = await fetch('/api/lootlocker/config-check');
      if (r.ok) {
        let contentType = r.headers.get("content-type");
        if (contentType && contentType.includes("application/json")) {
          let d = await r.json();
          if (d.hasLootLocker) {
            this.hasLootLockerConfig = true;
            this.isDirectMode = false;
            this.log('Server proxy active (hasLootLocker = true)', 'success');
            return d;
          } else {
            this.log('Server proxy reported that LOOTLOCKER_API_KEY is not set on server side.', 'warning');
          }
        }
      } else {
        this.log(`Server configuration check returned status: ${r.status}`, 'warning');
      }
    } catch (e) {
      this.log(`Server check failed/unavailable: ${e.message} (Possibly static hosting)`, 'info');
    }

    // 2. Fallback to direct client-side requests if Express is missing but VITE env vars are available
    const clientKey = this.apiKey;
    const clientDomain = this.domainKey;
    if (clientKey && clientKey !== 'YOUR_API_KEY_HERE' && clientKey.trim() !== '' && clientDomain) {
      this.hasLootLockerConfig = true;
      this.isDirectMode = true;
      this.log(`Static hosting mode active. Direct connection via Domain: ${clientDomain}`, 'success');
      return true;
    }

    this.log('No LootLocker credentials found on server or compiled client-side. Leaderboards disabled.', 'error');
    this.hasLootLockerConfig = false;
    return false;
  },

  syncTotalCoins: async function() {
    let localTotal = secureStorage.getItem<number>('JUMP_TOTAL_COINS', 0);
    let remoteTotal = 0;

    // Attempt to fetch remote coins
    try {
      if (this.coinLeaderboardId && await this.init()) {
        let r;
        if (this.isDirectMode) {
          let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.coinLeaderboardId}/member/${this.playerId}`;
          r = await fetch(url, {
            headers: {
              'Content-Type': 'application/json',
              'x-session-token': this.sessionToken
            }
          });
        } else {
          r = await fetch(`/api/lootlocker/leaderboards/member?member_id=${this.playerId}&session_token=${encodeURIComponent(this.sessionToken)}&leaderboard_id=${this.coinLeaderboardId}`);
        }

        if (r.ok) {
          let d = await r.json();
          if (d && typeof d.score === 'number' && d.score > 0) {
            remoteTotal = d.score;
            if (remoteTotal > localTotal) {
              this.log(`Remote coins (${remoteTotal}) > Local coins (${localTotal}). Syncing to local.`, 'info');
              localTotal = remoteTotal;
              secureStorage.setItem('JUMP_TOTAL_COINS', localTotal);

              // Try to update global game state if running
              if (typeof (window as any).game !== 'undefined') {
                (window as any).game.totalCoins = localTotal;
              }
              // Force shop coin display update if element exists
              let el = document.getElementById('shopCoinCounter');
              if (el) el.innerText = localTotal.toString();
            }
          }
        }
      }
    } catch(e) {
      console.warn("Failed to fetch remote coins", e);
    }

    if (localTotal > 0 && localTotal > remoteTotal) {
      await this.submitCoinScore(localTotal, getLang());
    }
  },

  submitPendingScores: async function() {
    try {
      let pending = JSON.parse(safeStorage.getItem('LL_PENDING_SCORES') || '[]');
      if (pending && pending.length > 0) {
        this.log(`Found ${pending.length} pending scores, attempting to submit...`, 'info');
        let remaining = [];
        for (let s of pending) {
           let success = await this.submitScore(s.alt, s.coins, s.t, s.lang, true);
           if (!success) remaining.push(s);
        }
        safeStorage.setItem('LL_PENDING_SCORES', JSON.stringify(remaining));
      }
    } catch(e) {
      safeStorage.removeItem('LL_PENDING_SCORES');
    }
  },
  init: async function() {
    const isConfigured = await this.checkConfig();
    if (!isConfigured) {
      this.log('Initialization aborted (Not Configured)', 'error');
      return false;
    }


    if (!this.playerIdentifier) {
      this.playerIdentifier = safeCrypto.generateRandomId('p');
      safeStorage.setItem('LL_PID', this.playerIdentifier);
      this.log(`Generated new Player Identifier: ${this.playerIdentifier}`, 'info');

    } else {
      this.log(`Loaded existing Player Identifier: ${this.playerIdentifier}`, 'info');
    }

    if (this.sessionToken) {
      this.log('Active session token already loaded.', 'success');
      return true;
    }

    try {
      let r;
      let url = '';
      if (this.isDirectMode) {
        url = `https://${this.domainKey}.api.lootlocker.io/game/v2/session/guest`;
        this.log(`POSTing to Direct API: ${url}`, 'info');
        r = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            game_key: this.apiKey,
            player_identifier: this.playerIdentifier,
            game_version: this.version.replace('v', '')
          })
        });
      } else {
        url = '/api/lootlocker/session/guest';
        this.log(`POSTing to Server Proxy: ${url}`, 'info');
        r = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            player_identifier: this.playerIdentifier,
            game_version: this.version.replace('v', '')
          })
        });
      }

      this.log(`Session response status: ${r.status}`, 'info');
      let d = await r.json();

      if (!r.ok) {
        this.log(`Session initialization error: ${JSON.stringify(d)}`, 'error');
        return false;
      }

      if (d.session_token) {
        this.sessionToken = d.session_token;
        setTimeout(() => this.submitPendingScores(), 2000);
        this.playerId = d.player_id;
        safeStorage.setItem('LL_SYS_PLAYER_ID', this.playerId);
        this.log(`Session connected successfully! Player ID: ${this.playerId}`, 'success');

        // Use client-generated or loaded customizable player name (e.g., "JPN XY")
        try {
          let localName = getPlayerName();
          let tn = document.getElementById('gamePlayerName');
          if (tn) tn.innerText = 'ID: ' + localName;
          this.setPlayerName(localName);
        } catch(e) {}

        return d;
      }
      this.log('No session token in response data.', 'error');
      return false;
    } catch (e) {
      this.log(`Session guest login failed: ${e.message}`, 'error');
      return false;
    }
  },


  getTimeAttackScores: async function(lm = 2000) {
    if (!this.taLeaderboardId) return null;
    this.log(`Attempting to fetch all TA scores...`, 'info');
    if (!await this.init()) return null;
    try {
      let allItems: any[] = [];
      let headers: any = { 'Content-Type': 'application/json' };
      if (this.isDirectMode) {
        headers['x-session-token'] = this.sessionToken;
      }

      let fetchPage = async (cursor?: any) => {
        let afterQuery = cursor ? `&after=${encodeURIComponent(cursor)}` : '';
        if (this.isDirectMode) {
          let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.taLeaderboardId}/list?count=${lm}${afterQuery}`;
          return await fetch(url, { headers });
        } else {
          return await fetch(`/api/lootlocker/leaderboards/list?count=${lm}${afterQuery}&session_token=${encodeURIComponent(this.sessionToken)}&leaderboard_id=${this.taLeaderboardId}`, { headers });
        }
      };

      let r = await fetchPage();
      let d = await r.json();
      if (!r.ok) return null;
      if (d.items) allItems.push(...d.items);

      while (d.pagination && d.pagination.next_cursor && d.items && d.items.length > 0 && allItems.length < (d.pagination.total || 10000)) {
        let nextR = await fetchPage(d.pagination.next_cursor);
        if (!nextR.ok) break;
        d = await nextR.json();
        if (d.items && d.items.length > 0) {
          allItems.push(...d.items);
        } else {
          break;
        }
      }

      let validItems = [];
      allItems.forEach(i => {
        let m = null;
        try { m = JSON.parse(i.metadata); } catch(e) {}
        if (m && m.t) {
            let playerName = (i.player && i.player.name) ? i.player.name : '???';
            validItems.push({ id: i.member_id, _originalRank: i.rank, alt: m.alt, coins: m.coins, lang: m.lang, n: playerName, t: 1000000000 - i.score });
        }
      });
      // Sort by lowest time
      validItems.sort((A, B) => A.t - B.t);
      validItems.forEach((v, idx) => v.rank = idx + 1);
      return validItems;
    } catch(e) {
      this.log(`TA Score fetch failed: ${e.message}`, 'error');
      return null;
    }
  },

  getMemberScore: async function() {
    if (!await this.init()) return null;
    try {
      let r;
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.leaderboardId}/member/${this.playerId}`;
        r = await fetch(url, {
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          }
        });
      } else {
        r = await fetch(`/api/lootlocker/leaderboards/member?member_id=${this.playerId}&session_token=${encodeURIComponent(this.sessionToken)}`);
      }
      if (r.ok) {
        let d = await r.json();
        if (d && typeof d.score === 'number' && d.score > 0 && d.rank !== 0) {
          let score = d.score;
          let alt = Math.floor(score / 1000);
          let coins = score % 1000;
          let time = 0;
          let lang = null;
          let rank = d.rank || null;
          try {
            if (d.metadata) {
              let m = JSON.parse(d.metadata);
              time = m.t ? m.t * 1000 : 0;
              if (m.lang) lang = m.lang;
            }
          } catch(e) {}
          return { alt, coins, time, lang, rank };
        } else {
          return { notFound: true };
        }
      } else if (r.status === 404 || r.status === 400) {
        return { notFound: true };
      }
    } catch(e) {
      this.log(`Failed to fetch member score: ${e.message}`, 'error');
    }
    return null;
  },

  getMemberTAScore: async function() {
    if (!this.taLeaderboardId) return null;
    if (!await this.init()) return null;
    try {
      let r;
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.taLeaderboardId}/member/${this.playerId}`;
        r = await fetch(url, {
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          }
        });
      } else {
        r = await fetch(`/api/lootlocker/leaderboards/member?member_id=${this.playerId}&session_token=${encodeURIComponent(this.sessionToken)}&leaderboard_id=${this.taLeaderboardId}`);
      }
      if (r.ok) {
        let d = await r.json();
        if (d && typeof d.score === 'number' && d.score > 0 && d.rank !== 0) {
          let time = 1000000000 - d.score;
          let alt = 144000;
          let coins = 0;
          let lang = null;
          try {
            if (d.metadata) {
              let m = JSON.parse(d.metadata);
              if (typeof m.alt === 'number') alt = m.alt;
              if (typeof m.coins === 'number') coins = m.coins;
              if (m.lang) lang = m.lang;
            }
          } catch(e) {}
          if (time > 0 && time < 86400000) {
            return { time, alt, coins, lang, rank: d.rank || null };
          } else {
            return { notFound: true };
          }
        } else {
          return { notFound: true };
        }
      } else if (r.status === 404 || r.status === 400) {
        return { notFound: true };
      }
    } catch(e) {
      this.log(`Failed to fetch member TA score: ${e.message}`, 'error');
    }
    return null;
  },

  setPlayerName: async function(name) {
    if (!await this.init()) return;
    try {
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/player/name`;
        fetch(url, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          },
          body: JSON.stringify({ name: name })
        });
      } else {
        fetch('/api/lootlocker/player/name', {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ name: name, session_token: this.sessionToken })
        });
      }
    } catch(e) {}
  },
  submitScore: async function(a, c, t, l, isRetry = false) {
    c = Math.min(c || 0, 999);
    this.log(`Attempting to submit score: ${a}m (Coins: ${c}, Lang: ${l})`, 'info');
    if (!await this.init()) {
      this.log('Score submission aborted (Init Failed)', 'error');
      return false;
    }
    let sc = a * 1000 + c;
    let sig = generateSignature(a, c, t, l);
    let meta = JSON.stringify({ alt: a, coins: c, lang: l, t: Math.floor(t / 1000), sig: sig });
    try {
      let r;
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.leaderboardId}/submit`;
        this.log(`Submitting score directly to: ${url}`, 'info');
        r = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          },
          body: JSON.stringify({ score: sc, metadata: meta })
        });
      } else {
        this.log('Submitting score via server proxy...', 'info');
        r = await fetch('/api/lootlocker/leaderboards/submit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            score: sc,
            metadata: meta,
            session_token: this.sessionToken
          })
        });
      }

      this.log(`Score submit response status: ${r.status}`, 'info');
      let d = await r.json();
      if (!r.ok) {
        this.log(`Score submission error: ${JSON.stringify(d)}`, 'error');
        if (isRetry && r.status >= 400 && r.status < 500 && r.status !== 429) {
           this.log('Permanent error during retry. Dropping score from pending queue.', 'error');
           return true; 
        }
        return false;
      }
      this.log('Score successfully registered on LootLocker!', 'success');
      return d;
    } catch (e) {
      this.log(`Score submission failed (offline?): ${e.message}`, 'error');
      if (!isRetry) {
        try {
          let pending = JSON.parse(safeStorage.getItem('LL_PENDING_SCORES') || '[]');
          pending.push({ alt: a, coins: c, lang: l, t: t, timestamp: Date.now() });
          pending.sort((A, B) => B.alt - A.alt || (B.coins || 0) - (A.coins || 0) || A.t - B.t);
          pending = pending.slice(0, 1);
          safeStorage.setItem('LL_PENDING_SCORES', JSON.stringify(pending));
          this.log('Score saved locally for offline queue (PB only).', 'warning');
        } catch (err) {
          safeStorage.removeItem('LL_PENDING_SCORES');
        }
      }
      return false;
    }
  },

  cachedLeaderboardEtag: null,
  cachedLeaderboardData: null,

  submitCoinScore: async function(coins, lang) {
    if (!this.coinLeaderboardId) {
      this.log('Coin submission skipped (no coin leaderboard ID)', 'info');
      return false;
    }
    this.log(`Attempting to submit Coin score: ${coins} (Lang: ${lang})`, 'info');
    if (!await this.init()) {
      this.log('Coin Score submission aborted (Init Failed)', 'error');
      return false;
    }

    let sc = Math.floor(coins);
    let sig = generateSignature(0, sc, 0, lang);
    let meta = JSON.stringify({ coins: sc, lang: lang, name: getPlayerName(), sig: sig });

    try {
      let r;
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.coinLeaderboardId}/submit`;
        r = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          },
          body: JSON.stringify({ score: sc, metadata: meta })
        });
      } else {
        r = await fetch('/api/lootlocker/leaderboards/submit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            score: sc,
            metadata: meta,
            session_token: this.sessionToken,
            leaderboard_id: this.coinLeaderboardId
          })
        });
      }
      if (!r.ok) {
        this.log('Coin Score submission error', 'error');
        return false;
      }
      this.log('Coin Score successfully submitted.', 'success');
      return await r.json();
    } catch (e) {
      this.log(`Coin Score submission failed: ${e.message}`, 'error');
      return false;
    }
  },

  submitTimeAttackScore: async function(t, a, c, l) {
    if (!this.taLeaderboardId) {
      this.log('Time Attack submission skipped (no TA leaderboard ID)', 'info');
      return false;
    }
    c = Math.min(c || 0, 999);
    this.log(`Attempting to submit TA score: time ${t}ms (Lang: ${l})`, 'info');
    if (!await this.init()) {
      this.log('TA Score submission aborted (Init Failed)', 'error');
      return false;
    }
    // Convert time to a score where higher is better, e.g. 100,000,000 - Math.floor(t)
    let sc = 1000000000 - Math.floor(t);
    let sig = generateSignature(a, c, t, l);
    let meta = JSON.stringify({ alt: a, coins: c, lang: l, t: Math.floor(t / 1000), sig: sig });
    try {
      let r;
      if (this.isDirectMode) {
        let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.taLeaderboardId}/submit`;
        r = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-session-token': this.sessionToken
          },
          body: JSON.stringify({ score: sc, metadata: meta })
        });
      } else {
        r = await fetch('/api/lootlocker/leaderboards/submit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            score: sc,
            metadata: meta,
            session_token: this.sessionToken,
            leaderboard_id: this.taLeaderboardId
          })
        });
      }
      if (!r.ok) {
        this.log('TA Score submission error', 'error');
        return false;
      }
      this.log('TA Score successfully submitted.', 'success');
      return await r.json();
    } catch (e) {
      this.log(`TA Score submission failed: ${e.message}`, 'error');
      return false;
    }
  },

  getScores: async function(lm = 2000) {
    this.log(`Attempting to fetch all scores (count: ${lm})...`, 'info');
    if (!await this.init()) {
      this.log('Score fetch aborted (Init Failed)', 'error');
      return null;
    }
    try {
      let allItems: any[] = [];
      let headers: any = {
        'Content-Type': 'application/json'
      };
      if (this.cachedLeaderboardEtag) {
        headers['If-None-Match'] = this.cachedLeaderboardEtag;
      }

      let fetchPage = async (cursor?: any) => {
        let afterQuery = cursor ? `&after=${encodeURIComponent(cursor)}` : '';
        if (this.isDirectMode) {
          let url = `https://${this.domainKey}.api.lootlocker.io/game/leaderboards/${this.leaderboardId}/list?count=${lm}${afterQuery}`;
          headers['x-session-token'] = this.sessionToken;
          return await fetch(url, { headers });
        } else {
          return await fetch(`/api/lootlocker/leaderboards/list?count=${lm}${afterQuery}&session_token=${encodeURIComponent(this.sessionToken)}`, { headers });
        }
      };

      let r = await fetchPage();
      if (r.status === 304 && this.cachedLeaderboardData) {
        this.log('304 Not Modified: Using cached scores', 'success');
        return this.cachedLeaderboardData;
      }

      let d = await r.json();
      if (!r.ok) {
        this.log(`Score fetch error: ${JSON.stringify(d)}`, 'error');
        return null;
      }

      if (r.headers.get('ETag')) {
        this.cachedLeaderboardEtag = r.headers.get('ETag');
      }

      if (!d.items) {
        this.log('No items returned in score list.', 'warning');
        return null;
      }

      allItems.push(...d.items);

      while (d.pagination && d.pagination.next_cursor && d.items && d.items.length > 0 && allItems.length < (d.pagination.total || 10000)) {
        let nextR = await fetchPage(d.pagination.next_cursor);
        if (!nextR.ok) break;
        d = await nextR.json();
        if (d.items && d.items.length > 0) {
          allItems.push(...d.items);
        } else {
          break;
        }
      }

      this.log(`Successfully fetched ${allItems.length} records!`, 'success');

      let validItems = [];
      allItems.forEach(i => {
        let m = { alt: FLR(i.score / 1000), coins: i.score % 1000, lang: '---', t: 0, sig: '' };
        try {
          if (i.metadata) m = JSON.parse(i.metadata);
        } catch (e) {}

        let isValid = true;
        if (m.sig) {
            let expectedSig = generateSignature(m.alt, m.coins, (m.t || 0) * 1000, m.lang);
            if (expectedSig !== m.sig) isValid = false;
        } else {
            isValid = false;
        }

        // Impossible speed check (max theoretical speed is ~3600m/s)
        if (m.t && m.t > 0) {
            if (m.alt / m.t > 6000) isValid = false;
        }

        // Exclude 0m scores
        if (!m.alt || m.alt <= 0) {
            isValid = false;
        }

        if (isValid) {
            let playerName = (i.player && i.player.name) ? i.player.name : '???';
            validItems.push({ id: i.member_id, _originalRank: i.rank, alt: m.alt, coins: m.coins, lang: m.lang, n: playerName });
        }
      });

      // Re-assign ranks based on filtered list
      validItems.forEach((v, idx) => {
         v.rank = idx + 1;
      });

      this.cachedLeaderboardData = validItems;
      return validItems;

    } catch (e) {
      this.log(`Score fetch failed (offline?): ${e.message}`, 'error');
      return null;
    }
  },

  resetPlayerSession: function() {
    this.log('Resetting player identifier and session...', 'warning');
    safeStorage.removeItem('LL_PID');
    safeStorage.removeItem('LL_SYS_PLAYER_ID');
